root=Path(__file__).resolve().parents[2]
# Each operation has a concrete result shape; route owns acceptance and returns.
items=[
('Прочитай полную конституцию Ш-0 и обязательные нормы. Сверь задачу, режим, разрешённое действие, версии route/prompt/attempt и пакет БА. До чтения норм клиентский материал не разбирай.', 'run_id, task_id, attempt, mode, authorized_action, route_version, prompt_version, rules[{id,version,locator,read_range}], capabilities, missing_rules', 'Нет полной конституции: blocked AIN-01; попроси у БА текст нормы, не начинай AIN-02.'),
('Собери только уже имеющиеся материалы у БА. Просмотри весь доступный ввод; перечисли файлы, версии, права, диапазоны и недостающее без интерпретации. Анкета Ш-А — предложение подтвердить уже известное, пропуск оставляет unknown.', 'materials[{id,name,version,author_role,locator,access,read_range,sensitivity}], questionnaire, missing_documents', 'БА пропустил анкету: сохрани неизвестные величины; не подставляй 0 и не задавай stakeholder-вопросы БА.'),
('Дай каждому источнику устойчивый ID; различи raw Заказчика, продуктовую БЗ, норму, вывод, пример и гипотезу. Зафиксируй полномочия автора, дату, доступ, версию, locator и фактически прочитанный диапазон. Источник не равен утверждению.', 'sources[{source_id,kind,owner,date,version,locator,access,read_range}], claims[{claim_id,source_ids,kind,applicability}]', 'Цитата из БЗ не становится словами Заказчика. Частично прочитанный файл не получает статус полного чтения.'),
('Раздели весь ввод на независимо проверяемые атомы. Сохрани исходную цитату отдельно, условия, отрицания, единицы, диапазоны, роли, исключения и обратные ссылки. Вывод из двух цитат — отдельный атом с обеими посылками. Разные условия не дедуплицируй.', 'atoms[{id,raw_locator,raw_fragment,statement,kind,actor,action,object,conditions,quantifier,units,exceptions,source_ids,derivation}], fragment_coverage', '2000 сотрудников не равно 2000 одновременных операторов. Потерянное отрицание: rework AIN-04.'),
('Проверь каждый атом: однозначность, атомарность, полнота, согласованность, достоверность, проверяемость, необходимость, актуальность, терминология, отраслевой смысл, полномочия, приватность, безопасность, наблюдаемость и отказные сценарии. Различи поведение, качество, ограничение, пример и вопрос. Исполнимость здесь только предпосылка для 12.', 'quality[{atom_id,dimension,result,basis}], defects[{id,atom_ids,type,severity,blocker,basis,resolution}], denominator, residual_risk', 'Чек-лист приёмки не единственный источник ФТ. Пример стека и API-workaround не становятся бизнес-требованием.'),
('Построй граф атом → возможность → компонент → источник. Отдельно прямые, опорные и внешние компоненты; ЛК, права, настройки, хранение, события, интерфейсы, лицензии. Определи поставку и ответственность сторон. Для каждого компонента new/delta/без изменения/unknown — пока candidate.', 'components[{id,kind,delivery_owner,scope,change_candidate,basis}], edges[{atom_id,capability,component_id,dependency,source_id}]', 'Новый коннектор не отменяет дельту ЛК. Исключённый компонент с зависимостью остаётся в графе; это не само по себе противоречие.'),
('Составь план поиска по каждому атому, компоненту и ребру. Начни с официальной Mango-БЗ, затем проверь внешнюю границу при зависимости/неприменимости/запросе БА. Укажи запросы, документы, версии, критерии релевантности и остановки. Расширение доступа и области согласует БА.', 'retrieval_plan[{atom_id,component_id,source,query,version,coverage_target,stop_criterion}], permissions, frontier', 'Поиск только по названию API не закрывает сценарий. Неизвестный адрес — запрос документа БА, не бизнес-вопрос Заказчику.'),
('Прочитай применимые официальные внешние и нормативные документы инструментом, который реально доступен. Сохрани URL, версию/дату, раздел, короткую дословную выдержку, диапазон и способ чтения. Отдельно проверь применимость и точный смысл. Snippet и HTTP 200 не доказывают чтение.', 'web_receipts[{source_id,url,version,retrieved_at,method,read_range,locator,excerpt,access,applicability}], gaps', 'Нет web/доступа: access_gap и blocked зависимого вывода; запроси документ у БА, не имитируй вызов.'),
('Прочитай выбранные разделы продуктовой и внешней БЗ. В auto: runtime README → MAP.json → product_ids → sections_toc по title → относящиеся разделы; sections_map только для hint/страниц. Manual/none и дополнения БА сохраняй. Не читай весь каталог. Cache пригоден только при принятии, той же версии и применимости.', 'knowledge_receipts[{source_id,product_id,version,locator,excerpt,read_range,method,access,applicability}], cache_reuse, gaps', 'Пустая выдача = empty, отсутствие инструмента = access_gap; ни то ни другое не означает запрет функции. Другой класс/расширение — решение БА.'),
('Сверь покрытие всех узлов и рёбер, включая обе границы интеграции. Похожие услуги, каналы, хранение и отображение проверяй отдельно. Новый компонент возвращает к 06/07. На каждом проходе фиксируй прирост evidence; два прохода без прироста при открытом frontier — blocked, новый источник может разрешить БА.', 'coverage[{node_or_edge,source_ids,result,gap_id}], frontier, pass_number, evidence_delta, no_progress_passes', 'Одной страницы API недостаточно. Незакрытая зависимость → возврат AIN-07, не автоматический допуск.'),
('Сопоставь коллизии по версиям и применимости; приведи обе цитаты. Свяжи роли, события, состояния, время и асинхронность между атомами. Официальный URL сам по себе не решает конфликт. Решение БА сохраняет основание и ограничения; новые evidence возвращают к извлечению.', 'conflicts[{id,claim_ids,quotes,versions,applicability,impact,ba_decision,status}], open_conflicts', 'Артефакт готов после события, UC требует его в момент события: конфликт, повторная проверка; не усредняй формулировки.'),
('Оцени возможность сейчас по каждому атому и всем его условиям, отдельно от «можно разработать». Да требует полного совпадения; частично — явного остатка; нет — положительного доказательства отсутствия/ограничения; иначе unknown. Докажи точное утверждение в своей продуктовой границе.', 'feasibility[{atom_id,component_id,verdict,evidence_ids,conditions,delta,unknown_reason}], future_development_candidates', 'API и аналогия с amoCRM не доказывают полный HDE-сценарий. VERIFIED источника не означает «Да» по исполнимости.'),
('Представь БА прямой, опорный и внешний пул, версии, матрицу покрытия, исключения и пробелы. По спорным тезисам accept/partial/reject с основанием; частичное согласие относится только к названному тезису. Не объявляй пул принятым за БА.', 'pool_version, components, exclusions, coverage, gaps, decisions[{claim_id,outcome,basis,actor,date,locator}]', 'Общее «да» после нескольких тезисов не подтверждает их все. Непринятый пул блокирует словарь и допуск.'),
('Составь только раздел 1 после принятия пула. Приоритет словаря D0 → выбранный отраслевой словарь; определение «род + отличительный признак», без требований/примеров UI. Различай близкие номера, UI, роли, услуги и моменты. Разное значение одного слова — два понятия со связью.', 'section1[{term,definition,product_ids,source_ids,unknown}], glossary_version, discrepancies', 'Нет определения: unknown с пробелом, не отраслевое угадывание. Раздел 2 здесь запрещён.'),
('Сведи все дефекты 05/10/11/12, включая НФТ и внешние границы. Перед каждым новым пробелом проверь весь ввод и БЗ текущих версий. Каждый дефект либо закрыт evidence, либо связан с вопросом/явной гипотезой; пока выдай реестр, не финальные вопросы.', 'gaps[{id,atom_ids,defect_ids,checked_locations,impact,blocker,resolution_kind,question_id,hypothesis_id}], coverage', 'Ответ уже есть в ТЗ: закрой пробел ссылкой. Отклонение старого вопроса без основания не закрывает дефект.'),
('Сформулируй только остаточные stakeholder-вопросы нумерованным списком, без таблицы. Каждый пункт: Q-ID; Заказчику; одно нейтральное бизнес-решение; атом/дефект; что и где проверено; влияние. Внутренние факты Mango не спрашивай Заказчика; архитектуру не перекладывай на него. Передачу выполняет БА.', 'Нумерованный список: 1. Q-ID; Заказчику; вопрос; атомы/дефекты; проверенные места; влияние. Если вопросов нет: «Вопросы Заказчику: [] — проверено и пусто», на review БА.', 'Пауза/analysis-only: финальный список не выдавай. Точное покрытие → пустой список, не искусственные вопросы.'),
('Запроси поэлементное решение БА о пакете вопросов: принять, отклонить с доказанным закрытием причины, доработать, принять явную гипотезу. БА курирует пакет и не становится адресатом stakeholder-вопроса. Отказ без закрытия дефекта сохраняет блокер. Молчание не решение.', 'question_decisions[{q_id,outcome,basis,defect_resolution,actor,date,locator}], unresolved, accepted_hypothesis_candidates', 'БА отклонил вопрос о границе поставки без ответа/гипотезы: rework 15/16; раздел 2 не создавай.'),
('Прими новые данные с автором/датой/источником. Различи customer_answer и добровольную ba_hypothesis: владелец, текст, причина, риск, область, срок/триггер проверки, атомы и явное принятие. Сверь связанные ответы; общие слова и частичное согласие не закрывают остаток.', 'updates[{id,kind,author,date,source_id,atom_ids,text}], hypotheses[{id,owner,risk,scope,review_trigger,accepted_by,decision_locator}], unresolved', 'Гипотеза без принятия или с критическим риском безопасности/прав/законности не допускает продолжение; не выдавай её за ответ клиента.'),
('Обнови атомы без потери ID/условий: version и supersedes. Построй транзитивный impact set по derivation и отзови все зависимые выводы, решения и snapshot до повторного допуска. Новые продукты → 06, источники → 07…12, смысл/вопросы → 04/15. Нет обновлений — явно зафиксируй это.', 'change_set[{id,old_version,new_version,supersedes,basis}], impact_set, stale_results, return_targets, unchanged', 'Отзыв исключения или гипотезы отзывает AIN-21 и раздел 2 той версии; прежний допуск не наследуется.'),
('Подготовь один snapshot всей будущей спецификации: ID/версия, route/prompt/attempt, принятые результаты шагов, полный пул Mango/внешних БЗ, атомы, derivation, решения, словарь, вопросы, гипотезы, unknown и ограничения доступа. Изолируй candidate/rejected/stale. Попроси БА принять конкретную версию.', 'snapshot_id, snapshot_version, manifest, accepted_result_refs, sources, atoms, pool, glossary, questions, hypotheses, unknowns, superseded_decisions, ba_acceptance', 'Черновик не принят — не память фактов. Закрытый источник передай только разрешённой выжимкой/locator с видимым ограничением проверки.'),
('Составь протокол допуска к разделу 2 без самого текста раздела. Проверь принятый пул 13 и словарь 14, полную трассировку фрагментов, покрытие зависимостей, каждый дефект с evidence либо допустимой принятой гипотезой, review списка 16 (включая пустой), отсутствие pending/rework без допуска, принятый актуальный snapshot 20, квитанции. Решение принимает БА явно.', 'gate_id=AIN-21, task_id, attempt, route_version, snapshot_id, snapshot_version, criteria[{id,result,evidence}], blockers, decision{actor,date,outcome,locator}; outcome=allow|stop', 'Любой открытый блокер, stale snapshot, молчание, new, срочность, прежний Г-IN → stop. Принятие протокола и команда AIN-22 — отдельные действия.'),
('Перед первым словом раздела 2 проверь явное allow AIN-21 для той же задачи/попытки/route/snapshot и разрешение именно AIN-22. Составь только раздел 2 по стандарту: 2.1 контекст акторов/сценария, 2.2 нормализованная проблема, 2.3 цель, 2.4.1/2.4.2 границы; 2.5 по принятому пулу. КС1…7, ≤250 слов, фраза ≤20 слов (>25 дефект). 2.4.1 содержит виды сущностей/интерфейсов, документацию, тестирование и ввод; 2.4.2 исключения/платформенную границу, условия работы передай в 6.2. Только snapshot: каждое утверждение → атом/источник; неизвестное и гипотеза условны. Служебное отдельно.', 'section2_draft, trace[{sentence_id,atom_ids,source_ids,hypothesis_ids}], word_count, scope_coverage, deferred_6_2', 'Allow другого snapshot или отозванная гипотеза: blocked AIN-21. Новая смысловая проблема → 15. ФТ, ТТЗ и архитектуру не создавай.'),
('Проверь раздел 2 в обе стороны: каждый исходный атом/условие/исключение покрыт, каждая фраза имеет основание. Сверь мета-стандарт, роли/события/состояния/время, ID до/после правки, суммы по перечню, отсутствие новых фактов, условность гипотез и отсутствие служебного в выпуске. Подготовь BA-review, не прими за БА.', 'review[{criterion,result,locator,evidence}], missing_atoms, unsupported_sentences, edits, ba_decision_request', 'Редакционная правка → 22; смысловая потеря → 04/15 и новый AIN-21. Красивый текст не заменяет покрытие.'),
('Подготовь пакет Г-IN: принятые разделы 1/2, snapshot, актуальный допуск 21, review 23, продукты/стейкхолдеры/команды и все критерии действующего Г-IN. Рекомендуй A-CORE/возврат/CS с основанием; решает БА. Полный match в CS только его решением. Передай классификацию what/how/качество/ограничения/UC по версиям стандартов без написания будущих разделов; ФТ-NN без отдельного заголовка перед формулировкой, L1/L2, без L3.', 'handover{sections,snapshot,gate21,review23,pool,questions,hypotheses,risks,classification,standards_versions}, gate_in{criteria,recommendation,ba_decision}', 'Нет явного Г-IN: Ш-3 и one-shot A-CORE blocked. Не объявляй «готово»/«согласовано» за человека.')
]
route=json.loads((root/'docs/ba-processes/bcreq-a-in-route.json').read_text())
result={s['id']:{'action':row[0],'shape':row[1],'negative_example':row[2]} for s,row in zip(route['steps'],items)}
(root/'docs/ba-processes/bcreq-a-in-instructions.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
